// Zadania klasy 3: autorskie warianty ćwiczeń z zeszytu i tabliczka mnożenia z importu.
function buildGrade3(){
 const bank={}; let seed=3182026;
 const shuffle=arr=>{for(let i=arr.length-1;i>0;i--){seed=(Math.imul(seed,1664525)+1013904223)>>>0;const j=seed%(i+1);[arr[i],arr[j]]=[arr[j],arr[i]]}return arr};
 const task=(prompt,answer,steps,extra={})=>({prompt,answer:String(answer),steps,...extra});
 const pool=(id,counts,make)=>{bank[id]={};const seen=new Set();for(let l=3;l<=5;l++){const all=make(l);const uniq=shuffle(all).filter(q=>{if(seen.has(q.prompt))return false;seen.add(q.prompt);return true});if(uniq.length<counts[l-3])throw Error(id+' '+l+' '+uniq.length);bank[id][l]=uniq.slice(0,counts[l-3]);for(const q of uniq.slice(counts[l-3]))seen.delete(q.prompt)}};
 const times=(h,m)=>String(h).padStart(2,'0')+':'+String(m).padStart(2,'0');
 const tens=n=>Math.floor(n/10)*10,ones=n=>n%10;
 pool('add',[80,80,80],l=>{const a=[];for(let x=10;x<100;x++)for(let y=1;y<=100-x;y++){const s=ones(x)+ones(y);if(l===3?!(y<10&&s<=10||y>=10&&s<10):l===4?!(y>=10&&s===10):!(y>=10&&s>10))continue;a.push(task(`${x} + ${y}`,x+y,[`Rozłóż liczby na dziesiątki i jedności: ${x} = ${tens(x)} + ${ones(x)}, ${y} = ${tens(y)} + ${ones(y)}.`,`Dodaj dziesiątki: ${tens(x)} + ${tens(y)} = ${tens(x)+tens(y)}.`,`Dodaj jedności: ${ones(x)} + ${ones(y)} = ${s}.`,`${tens(x)+tens(y)} + ${s} = ${x+y}.`]))}return a});
 pool('sub',[47,47,46],l=>{const a=[];for(let x=11;x<=100;x++)for(let y=1;y<x;y++){if(l===3?!(y<10&&ones(x)>=y||y%10===0):l===4?!(y<10&&ones(x)<y||y>=10&&ones(x)>=ones(y)&&y%10!==0):!(y>=10&&ones(x)<ones(y)))continue;a.push(task(`${x} − ${y}`,x-y,[`Rozłóż ${y} na ${tens(y)} i ${ones(y)}.`,`${x} − ${tens(y)} = ${x-tens(y)}.`,`${x-tens(y)} − ${ones(y)} = ${x-y}.`]))}return a});
 pool('compare',[40,40,40],l=>{const a=[];for(let i=0;i<600;i++){const x=l===3?10+i%90:l===4?100+i%900:100+i%900;const y=i%5===0?x:l===3?(i*13+17)%100:l===4?(i*37+221)%1000:Math.max(0,x+(i%2===0?1:-1)*(i%9+1));a.push(task(`${x}  ?  ${y}`,x===y?'=':x<y?'<':'>',['Porównaj liczbę cyfr. Jeśli jest taka sama, porównuj cyfry od lewej.',x===y?`${x} i ${y} są równe.`:`${Math.max(x,y)} jest większe od ${Math.min(x,y)}.`,`Wstaw znak ${x===y?'=':x<y?'<':'>'}.`]))}return a});
 pool('order',[37,37,36],l=>{const a=[];for(let x=10;x<=100;x++)for(let y=2;y<=45;y++)for(const op of l===3?['+−','−+']:l===4?['−−','++']:['+−','−+']){if(l===3&&y>10||l===5&&y<11)continue;const mid=op[0]==='+'?x+y:x-y;if(mid<0||mid>100)continue;const z=l===3?3+(x+y)%8:11+(x+y)%29;const end=op[1]==='+'?mid+z:mid-z;if(end<0||end>100)continue;const s1=op[0]==='+'?'+':'−',s2=op[1]==='+'?'+':'−';a.push(task(`${x} ${s1} ${y} ${s2} ${z}`,end,['Dodawanie i odejmowanie wykonuj od lewej do prawej.',`${x} ${s1} ${y} = ${mid}.`,`${mid} ${s2} ${z} = ${end}.`]))}return a});
 pool('unknown',[54,53,53],l=>{const a=[];for(let x=1;x<=99;x++)for(let y=1;y<=100-x;y++){if(l===3&&!(x%10===0||y%10===0||x<10&&y<20))continue;if(l===4&&!(x>=10&&y>=10&&ones(x)+ones(y)<10))continue;if(l===5&&!(x>=10&&y>=10&&ones(x)+ones(y)>=10))continue;const s=x+y;const t=(x+y)%4;const variants=[
 task(`□ + ${y} = ${s}`,x,['Brakujący składnik obliczysz, odejmując znany składnik od sumy.',`${s} − ${y} = ${x}.`,`Sprawdzenie: ${x} + ${y} = ${s}.`]),
 task(`${y} + □ = ${s}`,x,['Odejmij znany składnik od sumy.',`${s} − ${y} = ${x}.`,`Sprawdzenie: ${y} + ${x} = ${s}.`]),
 task(`□ − ${y} = ${x}`,s,['Aby odtworzyć liczbę początkową, dodaj odjętą liczbę do wyniku.',`${x} + ${y} = ${s}.`,`Sprawdzenie: ${s} − ${y} = ${x}.`]),
 task(`${s} − □ = ${y}`,x,['Od liczby początkowej odejmij znany wynik.',`${s} − ${y} = ${x}.`,`Sprawdzenie: ${s} − ${x} = ${y}.`])];a.push(variants[t])}return a});
 pool('clock',[20,20,20],l=>{const a=[];for(let h=1;h<=11;h++)for(const m of l===3?[0,30]:l===4?[15,45]:[5,10,20,25,35,40,50,55])for(const pm of [false,true]){const H=h+(pm?12:0),answer=times(H,m);a.push(task(`Odczytaj zegar (${pm?'po południu':'przed południem'}). Wpisz godzinę w formacie HH:MM.`,answer,[`Krótka wskazówka pokazuje godzinę ${h}${m?' (i część następnej godziny)':''}.`,`Długa wskazówka pokazuje ${m} minut.`,pm?`Po południu dodaj 12 do godziny: ${h} + 12 = ${H}.`:'Przed południem nie dodawaj 12.',`Godzina: ${answer}.`],{clock:{h,m,pm}}))} // uniqueness for identical instruction via explicit variant key, restored after selection
 return a.map(q=>({...q,prompt:q.prompt+' #'+q.answer}))});
 for(const l of [3,4,5])for(const q of bank.clock[l])q.prompt=q.prompt.split(' #')[0];
 pool('time',[17,17,16],l=>{const a=[];const defs=l===3?[[15,'kwadransów','minut',1,8],[7,'tygodni','dni',1,8],[3,'kwartałów','miesięcy',1,4],[24,'dób','godzin',1,4]]:l===4?[[60,'godzin','minut',1,8],[60,'minut','sekund',1,8],[12,'lat','miesięcy',1,8],[15,'kwadransów','minut',9,16]]:[[60,'minut','godzin',1,8],[7,'dni','tygodni',1,8],[3,'miesięcy','kwartałów',1,8],[24,'godzin','dób',1,6]];for(const [factor,from,to,lo,hi] of defs)for(let k=lo;k<=hi;k++){const rev=l===5;const n=rev?k*factor:k;a.push(task(`Przelicz: ${n} (${from}) na ${to}.`,rev?k:k*factor,[rev?`Jedna jednostka docelowa odpowiada ${factor} jednostkom podanym.`:`Jedna jednostka podana odpowiada ${factor} jednostkom docelowym.`,rev?`${n} ÷ ${factor} = ${k}.`:`${k} × ${factor} = ${k*factor}.`]))}
 if(l===3)a.push(task('Ile godzin to pół doby?',12,['Doba ma 24 godziny.','24 ÷ 2 = 12.']),task('Ile miesięcy to pół roku?',6,['Rok ma 12 miesięcy.','12 ÷ 2 = 6.']));return a});
 pool('word',[34,33,33],l=>{const a=[];for(let x=2;x<=12;x++)for(let y=2;y<=10;y++){if(l===3){a.push(task(`W godzinę można przeczytać ${x} stron. Ile stron można przeczytać w ciągu ${y} godzin w tym samym tempie?`,x*y,[`W każdej godzinie przybywa ${x} stron.`,`${x} × ${y} = ${x*y} stron.`]))}else if(l===4){a.push(task(`Przejście 1 km zajmuje ${x*5} minut. Ile kilometrów można przejść w ${x*5*y} minut w tym samym tempie?`,y,[`Każdy kilometr zajmuje ${x*5} minut.`,`${x*5*y} ÷ ${x*5} = ${y} km.`]));a.push(task(`Napisanie jednej strony trwa ${x} minut. Ile minut zajmie napisanie ${y} stron?`,x*y,[`Pomnóż czas pisania jednej strony przez liczbę stron.`,`${x} × ${y} = ${x*y} minut.`]))}else {const seconds=60*x/y;if(!Number.isInteger(seconds))continue;const hour=8+(x%5),minute=50+(y%8),finish=hour*60+minute+x;const ans=times(Math.floor(finish/60),finish%60);a.push(task(`Test ma ${y} zadań. Każde zajmuje ${seconds} sekund. Start o ${times(hour,minute)}. O której koniec? Wpisz HH:MM.`,ans,[`${y} × ${seconds} = ${60*x} sekund.`,`${60*x} ÷ 60 = ${x} minut.`,`Dodaj ${x} minut do ${times(hour,minute)}.`,`Koniec o ${ans}.`]))}}return a});
 const tuples=[[7,4,3],[8,5,3],[4,9,3],[6,8,4],[9,9,5],[8,7,5],[7,6,4],[9,8,5],[9,5,3],[6,5,3],[4,7,3],[7,9,5],[8,4,3],[4,6,3],[9,4,3],[3,6,3],[6,6,4],[3,5,3],[5,4,3],[5,7,3],[6,4,3],[7,7,5],[8,8,5],[6,9,4]];
 bank.mul={3:[],4:[],5:[]};for(const [x,y,l] of tuples){const a=Math.max(x,y),b=Math.min(x,y),p=Math.floor(a/2),r=a-p;const steps=a===9?[`Zamiast 9 grup policz 10 grup po ${b}: 10 × ${b} = ${10*b}.`,`Odejmij jedną grupę: ${10*b} − ${b} = ${x*y}.`]:[`Podziel ${a} grup po ${b} na dwie części: ${p} i ${r}.`,`${p} × ${b} = ${p*b}, a ${r} × ${b} = ${r*b}.`,`Dodaj obie części: ${p*b} + ${r*b} = ${x*y}.`];bank.mul[l].push(task(`${x} × ${y}`,x*y,steps))}
 return bank;
}
export const grade3Bank=buildGrade3();
const remaining=new Map();
export function grade3Exercise(id,level){const pool=grade3Bank[id]?.[level];if(!pool?.length)return null;const key=id+':'+level;let bag=remaining.get(key);if(!bag?.length){bag=pool.slice();remaining.set(key,bag)}const i=Math.floor(Math.random()*bag.length);const q=bag.splice(i,1)[0];return {...q,steps:[...q.steps]};}
